const text = String($('Telegram Trigger').first().json.message.text || '').trim().toLowerCase().split('@')[0];
const orders = $('Get Orders Cmd').all().map(i => i.json).filter(o => o['Order ID']);
const meds = $('Get Medicines Cmd').all().map(i => i.json).filter(m => m['Medicine Name']);
const today = $now.setZone('Asia/Kolkata').toFormat('dd-MM-yyyy');
const LOW = 10;
const line = '━━━━━━━━━━━━━━';

const icon = q => Number(q) <= 0 ? '❌' : Number(q) <= LOW ? '⚠️' : '✅';

const help = '🛠 OWNER COMMANDS
' + line +
  '

📦 /todayorders
Aaj ke orders

💰 /totalsales
Aaj ki total sale

📋 /stock
Saari medicines ka stock' +
  '

🧾 /order + ID
Jis order ki details dekhni ho, uska ID likho
Jaise: /order 5  ya  /order5' +
  '

❓ /help
Ye list';

const todayOk = orders.filter(o =>
  String(o['Order Date'] || '').startsWith(today) &&
  String(o['Order Status'] || '').trim().toLowerCase() !== 'cancelled');

let reply = help;

if (text === '/todayorders') {
  reply = todayOk.length
    ? '📦 AAJ KE ORDERS (' + todayOk.length + ')
' + line + '

' + todayOk.map(o =>
        '🧾 Order #' + o['Order ID'] + '
👤 ' + o['Customer Name'] + '
💊 ' + o['Medicine Name'] + '
💰 ₹' + o['Total Price']).join('

')
    : '📦 AAJ KE ORDERS
' + line + '

Aaj abhi tak koi order nahi aaya.';
} else if (text === '/totalsales') {
  const sum = todayOk.reduce((s, o) => s + Number(o['Total Price'] || 0), 0);
  reply = '💰 AAJ KI SALE
' + line + '

📦 Orders: ' + todayOk.length + '
💵 Total: ₹' + sum;
} else if (text === '/stock') {
  reply = '📋 STOCK LIST
' + line + '

' +
    meds.map((m, i) => icon(m['Quantity']) + ' ' + (i + 1) + '. ' + m['Medicine Name'] + ' — ' + m['Quantity']).join('
') +
    '

' + line + '
✅ Theek   ⚠️ Kam   ❌ Khatam';
} else if (text === '/lowstock') {
  const low = meds.filter(m => Number(m['Quantity']) <= LOW);
  reply = low.length
    ? '⚠️ KAM STOCK (' + low.length + ')
' + line + '

' +
      low.map((m, i) => icon(m['Quantity']) + ' ' + (i + 1) + '. ' + m['Medicine Name'] + ' — ' + m['Quantity']).join('
')
    : '✅ Sab medicines ka stock theek hai.';
} else if (/^/order\s*\d+$/.test(text)) {
  const id = text.replace(/\D/g, '');
  const o = orders.find(x => String(x['Order ID']).replace(/\D/g, '') === id);
  reply = o
    ? '🧾 ORDER #' + o['Order ID'] + '
' + line +
      '

👤 Naam: ' + o['Customer Name'] +
      '
📞 Phone: ' + o['Contact Number'] +
      '
📍 Address: ' + o['Customer Address'] +
      '

💊 Medicine: ' + o['Medicine Name'] +
      '
🔢 Qty: ' + o['Quantity'] +
      '
💰 Total: ₹' + o['Total Price'] +
      '

📌 Status: ' + o['Order Status'] +
      '
🕒 Date: ' + o['Order Date']
    : '❌ Order #' + id + ' nahi mila.';
}

return [{ json: { text: reply } }];
